-- Hires (EV=H: first contract start) and leavers (EV=L: last paid month of staff with no active current contract) by month, branch, job and nationality. One text column LN = ev|ym|branch|job|nationality code|n.
-- Page with RN BETWEEN a AND b (windows of 190) because the MCP returns about 200 rows per reply. Branch = cost-centre prefix of the current job, job from CODES_MASTER type 250, nationality code = CODES_MASTER CODE_NO (type 105).
SELECT y.LN FROM (SELECT z.LN, ROW_NUMBER() OVER (ORDER BY z.LN) RN FROM (SELECT e.EV||'|'||e.YM||'|'||(CASE WHEN t.ORG IN ('001','002','003','004') THEN '0'||SUBSTR(t.ORG,3,1) ELSE SUBSTR(NVL(t.ORG,'??'),1,2) END)||'|'||NVL(j.DESCRIPTION,'?')||'|'||NVL(TO_CHAR(m.NATIONALITY_CODE),'?')||'|'||COUNT(*) LN FROM (SELECT STAFF_ID STF, 'H' EV, TO_CHAR(MIN(START_DATE),'YYYY-MM') YM FROM {P}PS_STAFF_CONTRACT GROUP BY STAFF_ID HAVING MIN(START_DATE)>=DATE '{FROM_DATE}' UNION ALL SELECT s.STAFF_ID, 'L', TO_CHAR(TO_DATE(MAX(s.YEAR_SALAR*100+s.MONTH_SALRY),'YYYYMM'),'YYYY-MM') FROM {P}PR_SALARY_TRANSACTION_D s WHERE s.STAFF_ID NOT IN (SELECT STAFF_ID FROM {P}PS_STAFF_CONTRACT WHERE STATUS='A' AND CURRENT_CONTRACT='Y') GROUP BY s.STAFF_ID HAVING MAX(s.YEAR_SALAR*100+s.MONTH_SALRY)>={FROM_YM}) e LEFT JOIN (SELECT STAFF_ID, MAX(ORGANIZATION_NO) ORG, MAX(STAFF_JOB_ID) JB FROM {P}PS_STAFF_INTERNAL_TRANSFERS WHERE CURRENT_JOB='Y' GROUP BY STAFF_ID) t ON t.STAFF_ID=e.STF LEFT JOIN {P}STAFF_MASTER m ON m.STAFF_ID=e.STF LEFT JOIN (SELECT USER_CODE, MAX(DESCRIPTION) DESCRIPTION FROM {P}CODES_MASTER WHERE CODE_TYPE=250 GROUP BY USER_CODE) j ON j.USER_CODE=t.JB GROUP BY e.EV, e.YM, (CASE WHEN t.ORG IN ('001','002','003','004') THEN '0'||SUBSTR(t.ORG,3,1) ELSE SUBSTR(NVL(t.ORG,'??'),1,2) END), NVL(j.DESCRIPTION,'?'), NVL(TO_CHAR(m.NATIONALITY_CODE),'?')) z) y WHERE y.RN BETWEEN 1 AND 190 ORDER BY y.RN
